// 1. Datos originales del nodo Edit Fields
const emailData = $('Edit Fields').first().json;

const customerName = (emailData.customer_name || "").replace(/^=/, "").trim();
const customerEmail = (emailData.customer_email || "").replace(/^=/, "").trim();
const emailSubject = (emailData.email_subject || "").replace(/^=/, "").trim();

// 2. Respuesta de Gemini
const geminiData = $input.first().json;
let rawText = geminiData.candidates?.[0]?.content?.parts?.[0]?.text || "";

rawText = rawText
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// 3. Parsear respuesta JSON
let aiResult = {};
let parseError = false;

try {
  aiResult = JSON.parse(rawText);
} catch (error) {
  parseError = true;
  aiResult = {
    categoria: "Error de Parseo",
    prioridad: "Alta",
    resumen: ["La IA no pudo analizar el email correctamente"],
    slack_channel: "#errores-n8n"
  };
}

const categoria = aiResult.categoria || "No clasificado";
const prioridad = aiResult.prioridad || "Alta";
let resumen = aiResult.resumen || ["No se pudo generar resumen"];
const slackChannel = aiResult.slack_channel || "#errores-n8n";

if (!Array.isArray(resumen)) {
  resumen = [resumen];
}

// 4. Construir el mensaje de Slack
let slackMessage;

if (parseError) {
  // Mensaje de error
  slackMessage = ` *Error al procesar email*

*De:* ${customerName || "No disponible"}
*Email:* ${customerEmail ? `<mailto:${customerEmail}|${customerEmail}>` : "No disponible"}
*Asunto:* ${emailSubject}

*Problema:* La IA no pudo analizar este email. Revisar manualmente.

*Respuesta cruda de la IA:*
\`\`\`
${rawText}
\`\`\`

_Automated with this n8n workflow_`;
} else {
  // Mensaje normal
  slackMessage = `*Nueva consulta recibida*

*De:* ${customerName || "No disponible"}
*Email:* ${customerEmail ? `<mailto:${customerEmail}|${customerEmail}>` : "No disponible"}
*Asunto:* ${emailSubject}

*Categoría:* ${categoria}
*Prioridad:* ${prioridad}

*Resumen:*
${resumen.map(item => `• ${item}`).join("\n")}

_Automated with this n8n workflow_`;
}

return [
  {
    json: {
      customer_name: customerName,
      customer_email: customerEmail,
      email_subject: emailSubject,
      categoria: categoria,
      prioridad: prioridad,
      resumen: resumen,
      slack_channel: slackChannel,
      slack_message: slackMessage
    }
  }
];
